    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    long long L;
    if (!(cin >> n >> k >> L)) return 0;

    // Precompute factorials and inverse factorials up to n
    vector<int> fact(n + 1), invfact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = mulmod(fact[i - 1], i);
    invfact[n] = modpow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i) invfact[i - 1] = mulmod(invfact[i], i);

    auto C = [&](int nn, int rr) -> int {
        if (rr < 0 || rr > nn) return 0;
        return mulmod(fact[nn], mulmod(invfact[rr], invfact[nn - rr]));
    };

    // Precompute inverse of (2n+1)
    int inv2n1 = modpow(2 * n + 1, MOD - 2);

    // Precompute powers of 2 up to 2n
    vector<int> pow2(2 * n + 1);
    pow2[0] = 1;
    for (int i = 1; i <= 2 * n; ++i) pow2[i] = addmod(pow2[i - 1], pow2[i - 1]);

    // Precompute binomial coefficients C(n, t) for t=0..n
    vector<int> Cnt(n + 1);
    for (int t = 0; t <= n; ++t) Cnt[t] = C(n, t);

    int ans = 0;

    // For each t = number of segments covering a point
    for (int t = k; t <= n; ++t) {
        int cnt_t = Cnt[t];
        if (cnt_t == 0) continue;

        // For each i = number of segments entirely on left side
        for (int i = 0; i <= n - t; ++i) {
            int j = n - t - i;
            // i segments entirely left, j entirely right, t crossing
            // Probability factor for this (i,j,t) configuration:
            // C(n, t) * C(n-t, i) * 2^t / (2n+1)
            int ways = mulmod(cnt_t, C(n - t, i));
            ways = mulmod(ways, pow2[t]);
            ways = mulmod(ways, inv2n1);

            // Contribution sign: (-1)^{i+j} = (-1)^{n-t}
            if ((n - t) & 1) {
                ans = submod(ans, ways);
            } else {
                ans = addmod(ans, ways);
            }
        }
    }

    // Multiply by L modulo MOD
    ans = mulmod(ans, (L % MOD + MOD) % MOD);

    cout << ans << '\n';
    return 0;
}
